  it('fails on the patched build', () => {
    // An explicit !!float tag on an unsigned number must resolve under the
    // JSON schema: JSON floats do not require a sign.
    assert.strictEqual(load('!!float 5\n', { schema: JSON_SCHEMA }), 5);
    assert.strictEqual(load('!!float 0.5\n', { schema: JSON_SCHEMA }), 0.5);
    assert.strictEqual(load('!!float 1e3\n', { schema: JSON_SCHEMA }), 1000);
    // Signed values must keep working.
    assert.strictEqual(load('!!float -5\n', { schema: JSON_SCHEMA }), -5);
  });
});
